/* Three.js soft-companion-lab geometry, material and palette. One shared WebGL renderer. */
const Companion=(()=>{
const palette={idle:'#a7cde5',listening:'#8fcae7',thinking:'#b3c4e3',speaking:'#a7d7cf',success:'#aad5b9',waiting:'#e4d5ac',error:'#ddbda9'};
const map={ready:'idle',confirm:'waiting',indeterminate:'waiting',processing:'thinking',saving:'thinking',success:'success',speaking:'speaking',listening:'listening',error:'error',offline:'error',timeout:'error',unavailable:'error',cancelled:'waiting',rest:'idle',interrupted:'waiting'};
const players=new Map(),media=matchMedia('(prefers-reduced-motion: reduce)');let reduced=false,renderer,renderFrame,last=0;const appearance={motion:1,color:palette.idle,transmission:.58,roughness:.24};
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(1);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;}catch(error){console.warn('WebGL unavailable',error);}
if(!renderer){
 function paint(){document.querySelectorAll('canvas[data-companion]').forEach(c=>{c.dataset.renderer='compatibility';c.setAttribute('aria-label','软团 AI，兼容显示');const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h*.5);const k=Math.min(w/3.4,h/2.8);ctx.scale(k,k);const gradient=ctx.createRadialGradient(-.45,-.55,.05,0,0,1.4);gradient.addColorStop(0,'#fff3ed');gradient.addColorStop(.5,palette[map[c.dataset.companion]||'idle']);gradient.addColorStop(1,'#7299b4');ctx.fillStyle=gradient;ctx.beginPath();ctx.moveTo(-1.1,.5);ctx.bezierCurveTo(-1.5,-.2,-.7,-1.3,-.05,-.8);ctx.bezierCurveTo(.6,-1,1.4,-.4,1.1,.45);ctx.bezierCurveTo(.8,1,-.75,1,-1.1,.5);ctx.fill();for(const x of [-.28,.28]){ctx.fillStyle='#fff9f3';ctx.beginPath();ctx.ellipse(x,0,.16,.23,0,0,7);ctx.fill();ctx.fillStyle='#2d455c';ctx.beginPath();ctx.ellipse(x+.015,.01,.07,.115,0,0,7);ctx.fill();ctx.fillStyle='white';ctx.beginPath();ctx.arc(x-.015,-.05,.025,0,7);ctx.fill();}ctx.restore();});}
 return{refresh(){paint();if(!document.querySelector('.webgl-note')){const n=document.createElement('p');n.className='webgl-note';n.textContent='当前浏览器未开启 WebGL，角色使用兼容显示。';document.querySelector('.studio')?.append(n);}},setReduced(){paint();},palette,setAppearance(v){Object.assign(appearance,v);palette.idle=appearance.color;paint();}};}
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(36,1,.1,50);camera.position.set(0,.6,6.2);camera.lookAt(0,.1,0);
// A locally generated studio environment: no HDR downloads.
const room=new THREE.Scene();room.background=new THREE.Color('#eadedb');const box=new THREE.Mesh(new THREE.BoxGeometry(12,12,12),new THREE.MeshBasicMaterial({color:'#f7f0eb',side:THREE.BackSide}));room.add(box);
for(const [x,y,z,w,h,intensity] of [[-3,3,3,3,5,4],[4,2,1,2,4,2],[0,4,-3,4,2,3]]){const p=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({color:new THREE.Color(intensity,intensity,intensity)}));p.position.set(x,y,z);p.lookAt(0,0,0);room.add(p)}
const pmrem=new THREE.PMREMGenerator(renderer);const env=pmrem.fromScene(room,.12);scene.environment=env.texture;pmrem.dispose();
scene.add(new THREE.HemisphereLight('#fff6ef','#caa0b4',2));const light=new THREE.DirectionalLight('#fff6ea',3);light.position.set(-3,5,4);scene.add(light);const rim=new THREE.DirectionalLight('#e4c7ff',1.8);rim.position.set(3,2,-3);scene.add(rim);
const root=new THREE.Group(),bodyGroup=new THREE.Group();scene.add(root);root.add(bodyGroup);
const geo=new THREE.SphereGeometry(1,96,64);const pos=geo.attributes.position;const original=new Float32Array(pos.array);
for(let i=0;i<pos.count;i++){const x=original[i*3],y=original[i*3+1],z=original[i*3+2];const angle=Math.atan2(x,y);const lobe=1+.075*Math.cos(3*angle+.45)*(1-z*z);original[i*3]=x*lobe*1.18+.075*y*y;original[i*3+1]=y*lobe*.95;original[i*3+2]=z*.83;}
const material=new THREE.MeshPhysicalMaterial({color:new THREE.Color('#e9a3bc'),roughness:.24,metalness:0,transmission:.58,thickness:1.5,ior:1.36,clearcoat:.7,clearcoatRoughness:.19,attenuationColor:new THREE.Color('#ed9db7'),attenuationDistance:2.8,envMapIntensity:1.1});const body=new THREE.Mesh(geo,material);bodyGroup.add(body);
const eyes=[];for(const x of [-.29,.29]){const group=new THREE.Group();group.position.set(x,.1,.795);const white=new THREE.Mesh(new THREE.SphereGeometry(1,32,24),new THREE.MeshPhysicalMaterial({color:'#fff9f3',roughness:.32}));white.scale.set(.16,.225,.075);group.add(white);const pupil=new THREE.Mesh(new THREE.SphereGeometry(1,24,16),new THREE.MeshStandardMaterial({color:'#2d455c',roughness:.3}));pupil.position.set(.008,-.01,.07);pupil.scale.set(.069,.112,.029);group.add(pupil);const shine=new THREE.Mesh(new THREE.SphereGeometry(.022,12,8),new THREE.MeshBasicMaterial({color:'white'}));shine.position.set(-.012,.035,.099);group.add(shine);bodyGroup.add(group);eyes.push(group)}
const shadowCanvas=document.createElement('canvas');shadowCanvas.width=shadowCanvas.height=128;const ctx=shadowCanvas.getContext('2d');const grad=ctx.createRadialGradient(64,64,2,64,64,64);grad.addColorStop(0,'rgba(115,61,85,.27)');grad.addColorStop(1,'rgba(115,61,85,0)');ctx.fillStyle=grad;ctx.fillRect(0,0,128,128);const shadow=new THREE.Mesh(new THREE.PlaneGeometry(3.7,2.2),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=-1.17;scene.add(shadow);

function visible(c){if(!c.isConnected||c.closest('[hidden]'))return false;const r=c.getBoundingClientRect();return r.width>0&&r.height>0&&r.bottom>0&&r.top<innerHeight;}
function refresh(){for(const c of players.keys())if(!c.isConnected)players.delete(c);for(const c of document.querySelectorAll('canvas[data-companion]')){const state=map[c.dataset.companion]||'idle';let p=players.get(c);if(!p){p={state,phase:0,t:0,color:new THREE.Color(palette[state]),yaw:0,boost:0};players.set(c,p);c.addEventListener('click',()=>{p.boost=1;});}if(p.state!==state){p.state=state;p.phase=0;}c.dataset.renderer='three-webgl';c.dataset.motionState=state;c.setAttribute('aria-label','软团 AI · '+({idle:'陪伴',listening:'倾听',thinking:'思考',speaking:'回应',success:'完成',waiting:'等待补充',error:'需要重试'}[state]));}if(!renderFrame)renderFrame=requestAnimationFrame(tick);}
function tick(now){renderFrame=requestAnimationFrame(tick);if(now-last<33||document.hidden)return;const dt=Math.min((now-last)/1000,.05);last=now;
for(const [c,p] of players){if(!visible(c))continue;const a=(reduced||media.matches||c.dataset.static==='true')?0:appearance.motion;const state=p.state,rect=c.getBoundingClientRect(),staticKey=a===0?[state,rect.width,rect.height,appearance.color,appearance.transmission,appearance.roughness].join('|'):null;if(staticKey&&p.staticKey===staticKey)continue;p.staticKey=staticKey;p.t+=dt*a;p.phase+=dt*a;p.boost=Math.max(0,p.boost-dt*.8);const t=p.t;let Y=1+.018*Math.sin(t*1.9)*a,R=0,P=0,RX=0;
if(state==='listening'){Y+=.065*a;RX=.12*a;R=Math.sin(t*1.4)*.025*a;}
if(state==='thinking'){R=Math.sin(t*2.5)*.09*a;Y+=Math.sin(t*4)*.035*a;P=.025*Math.sin(t*3)*a;}
if(state==='speaking'){Y+=Math.sin(t*5)*.055*a;R=Math.sin(t*2)*.035*a;}
if(state==='waiting')R=-.14*a;
if(state==='error'){Y-=.1*Math.exp(-p.phase*.7)*a;RX=-.1*Math.exp(-p.phase*.7)*a;}
const jump=(state==='success'?Math.max(0,Math.sin(Math.min(p.phase,2.2)/2.2*Math.PI)):0)+Math.sin((1-p.boost)*Math.PI)*p.boost;
if(jump>0){P+=jump*.8*a;Y+=Math.sin(p.phase*8)*.13*jump*a;R+=Math.sin(p.phase*4)*.1*jump*a;}
bodyGroup.scale.set(1/Math.sqrt(Y),Y,1/Math.sqrt(Y));bodyGroup.position.y=P;bodyGroup.rotation.set(RX,0,R);
for(let i=0;i<pos.count;i++){const x=original[i*3],y=original[i*3+1],z=original[i*3+2];const wobble=1+a*.018*Math.sin(y*4+t*2.8)*Math.sin(x*3+t*1.7);pos.setXYZ(i,x*wobble,y,z*wobble);}pos.needsUpdate=true;geo.computeVertexNormals();
const bt=t%4.6,blink=bt>4.38?Math.max(.06,Math.abs(bt-4.49)/.11):1;for(const e of eyes){e.scale.y=state==='success'?.7:blink;e.rotation.z=state==='waiting'?-.06:0;}
if(a===0)p.color.set(state==='idle'?appearance.color:palette[state]);else p.color.lerp(new THREE.Color(state==='idle'?appearance.color:palette[state]),1-Math.exp(-dt*2));material.color.copy(p.color);material.transmission=appearance.transmission;material.roughness=appearance.roughness;root.rotation.set(0,p.yaw,0);shadow.scale.setScalar(1+P*.2);shadow.material.opacity=1-P*.35;
const r=c.getBoundingClientRect(),w=Math.max(80,Math.min(640,Math.round(r.width*Math.min(devicePixelRatio,1.5)))),h=Math.max(60,Math.round(w*r.height/r.width));if(c.width!==w||c.height!==h){c.width=w;c.height=h;}renderer.setSize(w,h,false);camera.aspect=w/h;camera.position.set(0,.6,c.closest('.message-avatar')?5:6.2);camera.lookAt(0,.1,0);camera.updateProjectionMatrix();renderer.render(scene,camera);const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);ctx.drawImage(renderer.domElement,0,0,w,h);c.dataset.motionTime=String(Math.round(p.phase*1000));
}}
document.addEventListener('visibilitychange',()=>{last=performance.now();if(!document.hidden)refresh();});media.addEventListener('change',refresh);
return {refresh,setReduced(v){reduced=v;refresh();},palette,setAppearance(v){Object.assign(appearance,v);palette.idle=appearance.color;refresh();}};})();
